import Link from "next/link";
import { loadContext } from "@/lib/booking/availability";
import { pageMember } from "@/lib/page";
import { todayIn } from "@/lib/time";
import { ManualBooking } from "@/components/ManualBooking";

export const metadata = { title: "Add reservation" };

export default async function NewReservationPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const { business } = await pageMember(slug, "reservations.create");
  const ctx = await loadContext(business.id);
  return (
    <div className="max-w-xl space-y-4">
      <Link href={`/app/${slug}`} className="font-semibold text-brand">Back to today</Link>
      <h1 className="text-3xl font-extrabold">Add a reservation</h1>
      <p className="text-ink-soft">For customers who phone or walk in. It is saved as booked by staff. Notice and party-size limits for online bookings do not apply here.</p>
      <ManualBooking businessId={business.id} slug={slug} today={todayIn(business.timezone)} services={ctx.services.filter((s) => s.active).map((s) => ({ id: s.id, name: s.name }))} />
    </div>
  );
}
